import json, math
from scipy.integrate import solve_ivp

# Implement the original model literally. Piecewise integration stops at production
# changes and at the first upward threshold crossing; q then freezes permanently.
AGES=[0.,4.,5.,8.,12.,20.,24.,36.,48.]
XC=.5

def run(alpha,tau,kn,kd,r,duration,q0,x0=0.,dtmax=.002):
    # State is x,q; production is on only before duration. Equality at x=xc
    # triggers arrest if the right-hand x derivative is positive; otherwise it
    # does not constitute an upward crossing.
    t=0.; y=[x0,q0]; arrested=False; rows=[]; tc=None; at_shutoff=None
    points=sorted(set([z for z in AGES if z<=48.] + [duration]))
    targets=sorted(set(points))
    def rhs(rate):
        def f(t,y):
            x,q=y
            return [alpha*rate-x/tau, -kd*q if arrested else kn*max(x-XC,0.)-kd*q]
        return f
    # Handle initial equality using the right-hand derivative.
    if abs(y[0]-XC)<1e-12 and alpha*r-y[0]/tau>0:
        arrested=True; tc=0.
    for target in targets:
        if target<t: continue
        if target==t:
            rows.append({'time_h':target,'x':y[0],'q':y[1],'arrested':arrested})
            continue
        rate=r if t<duration else 0.
        end=min(target,duration) if t<duration else target
        if end>t:
            def event(tt,yy): return yy[0]-XC
            event.direction=1; event.terminal=True
            sol=solve_ivp(rhs(rate),(t,end),y,rtol=1e-10,atol=1e-12,max_step=dtmax,events=None if arrested else event,dense_output=True)
            if not sol.success: raise RuntimeError(sol.message)
            if not arrested and len(sol.t_events[0]):
                tc=float(sol.t_events[0][0]); y=[float(sol.y_events[0][0][0]),float(sol.y_events[0][0][1])]; t=tc; arrested=True
                # Continue from event to requested boundary with q frozen.
                if end>t:
                    sol2=solve_ivp(rhs(rate),(t,end),y,rtol=1e-10,atol=1e-12,max_step=dtmax)
                    if not sol2.success: raise RuntimeError(sol2.message)
                    y=[float(sol2.y[0,-1]),float(sol2.y[1,-1])]; t=end
            else:
                y=[float(sol.y[0,-1]),float(sol.y[1,-1])]; t=end
        if abs(target-duration)<1e-10: at_shutoff={'time_h':duration,'x':y[0],'q':y[1],'arrested':arrested}
        if abs(target-round(target,10))<1e-8 and target in AGES:
            rows.append({'time_h':target,'x':y[0],'q':y[1],'arrested':arrested})
    return {'crossing_time_h':tc,'shutoff':at_shutoff,'observations':rows,'x_final':y[0],'q_final':y[1],'arrested':arrested}

